<?php
declare(strict_types=1);namespace App\Application\Projects;use App\Application\Profile\CapabilityStatementSynchronizer;use App\Models\CapabilityStatement;use App\Models\PersonProfile;use App\Models\Project;use App\Models\ProjectMatchDecision;
final class ProjectMatchingEngine{public function forProject(Project $p,string $actor,array $c):array{$required=[];foreach($p->required_capabilities as $label){$n=CapabilityStatementSynchronizer::normalize((string)$label);if($n!=='')$required[$n]=(string)$label;}if($required===[])return [];$hidden=ProjectMatchDecision::query()->where('project_id',$p->id)->where('actor_core_reference',$actor)->where('decision',ProjectMatchDecision::HIDDEN)->pluck('subject_profile_reference');$profiles=PersonProfile::query()->where('orientation_consent',true)->where('discovery_consent',true)->whereNotNull('discovery_reference')->whereNotNull('discovery_display_name')->when($hidden->isNotEmpty(),fn($q)=>$q->whereNotIn('discovery_reference',$hidden))->with(['capabilityStatements'=>fn($q)=>$q->whereNull('archived_at')->where('kind',CapabilityStatement::KIND_POSSESSED)->where('matching_consent',true)->where('visibility',CapabilityStatement::VISIBILITY_DISCOVERABLE)])->limit((int)$c['candidate_pool'])->get();$out=[];foreach($profiles as $profile){$matches=[];foreach($profile->capabilityStatements as $s){$normalized=CapabilityStatementSynchronizer::normalize((string)$s->normalized_label);if(isset($required[$normalized]))$matches[]=$required[$normalized];}$matches=array_values(array_unique($matches));if($matches===[])continue;$reasons=array_map(fn($x)=>"Cette personne déclare la capacité « {$x} », recherchée par le projet.",$matches);if($c['location_context']&&$p->location&&$profile->city&&mb_strtolower($p->location)===mb_strtolower($profile->city))$reasons[]="La personne et le projet sont situés à {$profile->city}.";if($c['participation_context']&&$profile->participation_mode===$p->participation_mode)$reasons[]='Le mode de participation déclaré correspond à celui du projet.';$out[]=['profile'=>$profile,'reasons'=>array_slice($reasons,0,(int)$c['max_reasons']),'match_count'=>count($matches)];}usort($out,fn($a,$b)=>[-$a['match_count'],mb_strtolower($a['profile']->discovery_display_name)]<=>[-$b['match_count'],mb_strtolower($b['profile']->discovery_display_name)]);return array_slice($out,0,(int)$c['max_results']);}}
